import {app,BrowserWindow,WebContentsView} from 'electron';
import assert from 'node:assert/strict';
import {mkdtemp,writeFile} from 'node:fs/promises';import {resolve,join} from 'node:path';
import {attachPlaywrightView} from '../../packages/browser/src/playwright-view.js';
import {UniversalFormSession} from '../../packages/browser/src/universal-form.js';
import {overrideProfile} from './override-profile.js';
import {fillOwnedCalendar} from '../../packages/browser/src/owned-calendar.js';
import {READ_UNIVERSAL_FORM,READ_UNIVERSAL_FORM_FOR_HOST_VERIFICATION} from '../../packages/browser/src/universal-read.js';
const dir=await mkdtemp(resolve('.backups/owned-calendar-'));app.setPath('userData',dir);await app.whenReady();const win=new BrowserWindow({show:false}),view=new WebContentsView({webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false,backgroundThrottling:false}});win.contentView.addChildView(view);view.setBounds({x:0,y:0,width:1100,height:900});
const html=(day:boolean)=>`<meta charset="utf-8"><style>body{font:16px sans-serif}button,td{padding:8px;cursor:pointer}input{height:30px}.phoenix-select__tipWrapper--visible{display:inline}.popup{position:fixed;left:200px;top:70px;background:white;border:1px solid;z-index:10}[hidden]{display:none!important}</style><form onsubmit="return false"><div class="form-item"><label>${day?'出生日期':'开始时间'}</label><div class="phoenix-select"><ul class="phoenix-select__content"><span id="tip"></span><li><input readonly id="date" class="phoenix-select__input"></li></ul></div></div><label>保留<input id="keep" value="KEEP"></label><input id="agreement" type="checkbox" aria-label="同意隐私协议"><button type="submit">提交申请</button></form><div id="calendar" class="popup" hidden></div><script>
window.clicks=0;window.selections=0;let year=2026,month=10,mode='${day?'day':'month'}';const root=document.getElementById('calendar'),input=document.getElementById('date');
function render(){root.innerHTML='';const header=document.createElement('div'),prev=document.createElement('button'),next=document.createElement('button'),y=document.createElement('button');for(const b of [prev,y,next])b.type='button';y.textContent=String(year);prev.setAttribute('aria-label','previous');next.setAttribute('aria-label','next');header.append(prev,y,next);root.append(header);y.onclick=()=>{mode='year';render()};prev.onclick=()=>{year-=mode==='year'?10:1;render()};next.onclick=()=>{year+=mode==='year'?10:1;render()};if(mode==='day'){const m=document.createElement('button');m.type='button';m.textContent=month+'月';m.onclick=()=>{mode='month';render()};header.append(m)}const table=document.createElement('table'),tbody=document.createElement('tbody');table.append(tbody);const gridBox=document.createElement('div'),help=document.createElement('button');help.type='button';help.textContent='日期帮助';gridBox.append(help,table);root.append(gridBox);const hidden=document.createElement('div');hidden.hidden=true;hidden.innerHTML='<table><tr><td>1</td><td>2</td><td>3</td><td>4</td></tr></table><table><tr><td>2024</td><td>2025</td><td>2026</td><td>2027</td></tr></table>';root.append(hidden);let values=mode==='year'?Array.from({length:12},(_,i)=>Math.floor(year/10)*10-1+i):mode==='month'?Array.from({length:12},(_,i)=>i+1):Array.from({length:new Date(year,month,0).getDate()},(_,i)=>i+1);if(mode==='day')values=[29,30,31,...values,1,2,3,4];for(let i=0;i<values.length;i++){if(i%3===0)tbody.append(document.createElement('tr'));const td=document.createElement('td');td.textContent=String(values[i])+(mode==='month'?'月':'');tbody.lastChild.append(td);td.onclick=()=>{window.clicks++;const value=values[i];if(mode==='year'){year=value;mode='month';render()}else if(mode==='month'){month=value;if(${day}){mode='day';render()}else commit()}else commit(value)}}}
function commit(day){const val=year+'-'+String(month).padStart(2,'0')+(day?'-'+String(day).padStart(2,'0'):'');document.getElementById('tip').textContent=val;document.getElementById('tip').className='phoenix-select__tipWrapper--visible';input.value='';root.hidden=true;window.selections++}input.onclick=()=>{window.clicks++;root.hidden=false;render()};input.onkeydown=e=>{if(e.key==='Escape')root.hidden=true};</script>`;
try{await view.webContents.loadURL('data:text/html;charset=utf-8,'+encodeURIComponent(html(false)));const attached=await attachPlaywrightView(view.webContents),page=attached.page;let checks=0;
for(const [day,value]of [[false,'2025-09'],[true,'2002-04-05']]as const){await page.goto('data:text/html;charset=utf-8,'+encodeURIComponent(html(day)));const result=await fillOwnedCalendar(page.locator('#date'),value,async()=>{},async()=>{assert.equal(await page.locator('#keep').inputValue(),'KEEP')});assert.equal(result.value,value);assert.equal(await page.locator('#calendar').isVisible(),false);assert.equal(await page.locator('#agreement').isChecked(),false);assert.equal(await page.evaluate('window.selections'),1);checks+=4;if(day){const normal:any=await page.evaluate(READ_UNIVERSAL_FORM),host:any=await page.evaluate(READ_UNIVERSAL_FORM_FOR_HOST_VERIFICATION);assert.equal(normal.fields.find((f:any)=>f.label==='出生日期').value,'[已有值]');assert.equal(host.fields.find((f:any)=>f.label==='出生日期').value,value);checks+=2;}}
// Missing day precision is rejected before navigation or selection. An
// explicit YYYY-MM-DD placeholder can be handled without opening the picker.
await page.goto('data:text/html;charset=utf-8,'+encodeURIComponent(html(true).replace('readonly id="date"','readonly placeholder="日期（年月日）" id="date"')));await assert.rejects(fillOwnedCalendar(page.locator('#date'),'2027-07',async()=>{},async()=>{}),/CALENDAR_PRECISION_UNSUPPORTED/);assert.equal(await page.evaluate('window.clicks'),0);assert.equal(await page.evaluate('window.selections'),0);checks+=3;
await page.goto('data:text/html;charset=utf-8,'+encodeURIComponent(html(true)));await assert.rejects(fillOwnedCalendar(page.locator('#date'),'2027-07',async()=>{},async()=>{}),/CALENDAR_PRECISION_UNSUPPORTED/);assert.equal(await page.evaluate('window.clicks'),1);assert.equal(await page.evaluate('window.selections'),0);assert.equal(await page.locator('#calendar').isVisible(),false);checks+=4;
// Persistent portal shells are not an open calendar after every grid is hidden.
await page.goto('data:text/html;charset=utf-8,'+encodeURIComponent(html(false).replace('root.hidden=true;window.selections++',"for(const child of root.children)child.hidden=true;root.style.width='180px';root.style.height='30px';window.selections++")));const retained=await fillOwnedCalendar(page.locator('#date'),'2025-09',async()=>{},async()=>{});assert.equal(retained.value,'2025-09');assert.equal(await page.locator('#calendar').isVisible(),true);assert.equal(await page.locator('#calendar table').first().isVisible(),false);checks+=3;
await page.goto('data:text/html;charset=utf-8,'+encodeURIComponent(html(false)));await assert.rejects(fillOwnedCalendar(page.locator('#date'),'2025',async()=>{},async()=>{}),/DATE_PRECISION_MISSING/);assert.equal(await page.evaluate('window.clicks'),0);checks+=2;
await assert.rejects(fillOwnedCalendar(page.locator('#date'),'2025-09',async()=>{throw Error('APPLICATION_CONTEXT_CHANGED:profile')},async()=>{}),/APPLICATION_CONTEXT_CHANGED/);assert.equal(await page.evaluate('window.selections'),0);checks+=2;
const profile=structuredClone(overrideProfile);profile.birthDate='2002-04-05';await page.goto('data:text/html;charset=utf-8,'+encodeURIComponent('<form onsubmit="return false"><label>出生日期<input id="batch-birth" type="date"></label><label>邮箱<input id="batch-email" type="email"></label><fieldset><legend>教育经历</legend><label>学校名称<input value="虚构甲大学"></label><label>学历<select id="batch-degree"><option value="">选择</option><option value="master">硕士</option></select></label><label>GPA<input id="batch-gpa"></label></fieldset><label>同意隐私协议<input id="batch-agreement" type="checkbox"></label><button type="submit">提交</button></form>'));const session=new UniversalFormSession(page,profile,async()=>profile,()=>1,new AbortController().signal);const observed=await session.inspect();const batch=await session.fillConfirmed(observed.observation);assert.equal(batch.verified,3);assert.equal(await page.locator('#batch-birth').inputValue(),profile.birthDate);assert.equal(await page.locator('#batch-degree').inputValue(),'master');assert.equal(await page.locator('#batch-gpa').inputValue(),'');assert.equal(await page.locator('#batch-agreement').isChecked(),false);checks+=5;session.close();
const {portraitProfile}=await import('./portrait-agent-main.js');await page.goto('data:text/html;charset=utf-8,'+encodeURIComponent('<form><label>语言能力<input id="language-summary"></label></form>'));const summarySession=new UniversalFormSession(page,portraitProfile as import('../../packages/shared/src/contracts.js').Profile,async()=>portraitProfile as import('../../packages/shared/src/contracts.js').Profile,()=>1,new AbortController().signal);const summaryView=await summarySession.inspect(),summaryResult=await summarySession.fillConfirmed(summaryView.observation);assert.equal(summaryResult.verified,1);const summary=await page.locator('#language-summary').inputValue();assert.ok(summary.includes('英语')&&summary.includes('日语'));assert.ok(!summary.includes('\n'));assert.equal((await summarySession.verify()).verified,1);checks+=4;summarySession.close();
const report={ok:true,checks,fictional:true,realEmployer:false,paidRequests:0};await writeFile(join(dir,'report.json'),JSON.stringify(report));console.log(JSON.stringify({ownedCalendar:true,...report}));await attached.close();win.destroy();app.exit(0);}catch(error){console.error(error);win.destroy();app.exit(1)}
